{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "main_title",
        "intro_text",
        "daily_nourishment_heading",
        "day1_card",
        "day2_card",
        "day3_card",
        "quick_actions_stack",
        "sources_stack"
      ]
    },
    "main_title": {
      "type": "Text",
      "props": {
        "text": "3-Day Easy Vegetarian Meal Plan",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This vegetarian meal plan provides approximately 1800 kcal per day, focusing on easy-to-prepare dishes and avoiding all nuts. It is designed for a single adult."
      },
      "children": []
    },
    "daily_nourishment_heading": {
      "type": "Text",
      "props": {
        "text": "Daily Nourishment (1800 kcal/day)",
        "variant": "h2"
      },
      "children": []
    },
    "day1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day1_header_stack",
        "day1_breakfast",
        "day1_lunch",
        "day1_dinner",
        "day1_snack"
      ]
    },
    "day1_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day1_icon",
        "day1_title"
      ]
    },
    "day1_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000771_01_1_cup-hot.svg"
      },
      "children": []
    },
    "day1_title": {
      "type": "Text",
      "props": {
        "text": "Day 1: Thursday, August 1, 2024",
        "variant": "h3"
      },
      "children": []
    },
    "day1_breakfast": {
      "type": "Text",
      "props": {
        "text": "Breakfast (approx. 450 kcal): Berry & Seed Oatmeal. 1/2 cup dry rolled oats cooked with 1 cup milk (dairy or non-dairy). Topped with 1/2 cup mixed berries and 2 tablespoons chia seeds. Optional: a touch of maple syrup or honey for sweetness."
      },
      "children": []
    },
    "day1_lunch": {
      "type": "Text",
      "props": {
        "text": "Lunch (approx. 600 kcal): Chickpea Salad Sandwich. 1 can (15 oz) chickpeas, mashed and mixed with 3 tbsp light mayonnaise or Greek yogurt, diced celery, diced red onion, and your favorite spices (e.g., curry powder, dill). Served on 2 slices of whole-wheat bread with lettuce. Side of 1 cup baby carrots."
      },
      "children": []
    },
    "day1_dinner": {
      "type": "Text",
      "props": {
        "text": "Dinner (approx. 600 kcal): Hearty Lentil & Vegetable Soup. 2 cups of homemade or store-bought lentil soup (made with brown lentils, carrots, celery, spinach, tomatoes, vegetable broth). Served with 2 slices of whole-wheat bread."
      },
      "children": []
    },
    "day1_snack": {
      "type": "Text",
      "props": {
        "text": "Snack (approx. 90 kcal): 1 medium apple."
      },
      "children": []
    },
    "day2_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day2_header_stack",
        "day2_breakfast",
        "day2_lunch",
        "day2_dinner",
        "day2_snack"
      ]
    },
    "day2_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day2_icon",
        "day2_title"
      ]
    },
    "day2_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000771_01_1_cup-hot.svg"
      },
      "children": []
    },
    "day2_title": {
      "type": "Text",
      "props": {
        "text": "Day 2: Friday, August 2, 2024",
        "variant": "h3"
      },
      "children": []
    },
    "day2_breakfast": {
      "type": "Text",
      "props": {
        "text": "Breakfast (approx. 450 kcal): Spinach & Feta Scramble with Toast. 2 large eggs scrambled with 1 cup fresh spinach and 1/4 cup crumbled feta cheese. Served with 2 slices of whole-wheat toast (lightly buttered)."
      },
      "children": []
    },
    "day2_lunch": {
      "type": "Text",
      "props": {
        "text": "Lunch (approx. 550 kcal): Leftover Lentil & Vegetable Soup. 2.5 cups of the hearty lentil and vegetable soup from Day 1."
      },
      "children": []
    },
    "day2_dinner": {
      "type": "Text",
      "props": {
        "text": "Dinner (approx. 700 kcal): Black Bean & Corn Quesadillas. 2 whole-wheat tortillas filled with 1/2 cup black beans (rinsed), 1/4 cup corn, and 1/2 cup shredded cheddar or Monterey Jack cheese. Cooked until golden and cheese is melted. Served with 1/4 cup salsa and 1/2 avocado, sliced."
      },
      "children": []
    },
    "day2_snack": {
      "type": "Text",
      "props": {
        "text": "Snack (approx. 70 kcal): 1 medium orange."
      },
      "children": []
    },
    "day3_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day3_header_stack",
        "day3_breakfast",
        "day3_lunch",
        "day3_dinner",
        "day3_snack"
      ]
    },
    "day3_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "day3_icon",
        "day3_title"
      ]
    },
    "day3_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000771_01_1_cup-hot.svg"
      },
      "children": []
    },
    "day3_title": {
      "type": "Text",
      "props": {
        "text": "Day 3: Saturday, August 3, 2024",
        "variant": "h3"
      },
      "children": []
    },
    "day3_breakfast": {
      "type": "Text",
      "props": {
        "text": "Breakfast (approx. 450 kcal): Greek Yogurt Parfait with Granola & Fruit. 1 cup plain Greek yogurt layered with 1/2 cup mixed berries, 1/2 cup nut-free granola, and 1 tablespoon honey."
      },
      "children": []
    },
    "day3_lunch": {
      "type": "Text",
      "props": {
        "text": "Lunch (approx. 550 kcal): Big Veggie & Egg Salad. Mixed greens base with cucumber, tomatoes, bell peppers, 1 hard-boiled egg (sliced), 1/2 cup roasted chickpeas (for crunch), and 3 tablespoons vinaigrette dressing. Served with 1 whole-wheat pita bread."
      },
      "children": []
    },
    "day3_dinner": {
      "type": "Text",
      "props": {
        "text": "Dinner (approx. 700 kcal): Whole-Wheat Pasta Primavera. 2 cups cooked whole-wheat pasta tossed with 1.5 cups mixed seasonal vegetables (e.g., broccoli florets, zucchini slices, bell pepper strips), a light tomato-based sauce, 2 tablespoons olive oil, and 1/4 cup grated Parmesan cheese."
      },
      "children": []
    },
    "day3_snack": {
      "type": "Text",
      "props": {
        "text": "Snack (approx. 115 kcal): 1 large apple."
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "quick_actions_heading",
        "find_recipes_button",
        "track_calories_button"
      ]
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "find_recipes_button": {
      "type": "Button",
      "props": {
        "label": "Find Vegetarian Recipes: Allrecipes Vegetarian"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.allrecipes.com/recipes/87/everyday-cooking/vegetarian/"
          }
        }
      },
      "children": []
    },
    "track_calories_button": {
      "type": "Button",
      "props": {
        "label": "Track Your Calories: MyFitnessPal"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.myfitnesspal.com/"
          }
        }
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "sources_heading",
        "usda_source_button",
        "academy_source_text"
      ]
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "usda_source_button": {
      "type": "Button",
      "props": {
        "label": "USDA FoodData Central"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://fdc.nal.usda.gov/"
          }
        }
      },
      "children": []
    },
    "academy_source_text": {
      "type": "Text",
      "props": {
        "text": "Academy of Nutrition and Dietetics: https://www."
      },
      "children": []
    }
  }
}
